import{c as r,$ as n,Q as a,j as s,g as t,o as i,n as l,m as d}from"./chunks/framework.Ce_49mA8.js";const v=JSON.parse('{"title":"Online Storefront & Web Showcase","description":"Built-in Jamstack SSG storefront generator, \\"Delicate Premium\\" design, sovereign E2EE checkout, multi-showcase management, and unified order inbox in OmniCraft ERP.","frontmatter":{"title":"Online Storefront & Web Showcase","description":"Built-in Jamstack SSG storefront generator, \\"Delicate Premium\\" design, sovereign E2EE checkout, multi-showcase management, and unified order inbox in OmniCraft ERP.","datePublished":"2026-08-20","dateModified":"2026-11-19","order":6},"headers":[],"relativePath":"docs/resources/web-store.md","filePath":"docs/resources/web-store.md","lastUpdated":1795046400000}'),c={name:"docs/resources/web-store.md"},g={id:"online-storefront-web-showcase",tabindex:"-1"};function u(h,e,p,m,b,f){const o=n("DocIcon");return a(),s("div",null,[t("h1",g,[i(o,{name:"showcase"}),e[0]||(e[0]=l(" Online Storefront & Web Showcase ",-1)),e[1]||(e[1]=t("a",{class:"header-anchor",href:"#online-storefront-web-showcase","aria-label":'Permalink to "Online Storefront & Web Showcase"'},"​",-1))]),e[2]||(e[2]=d('<p>The built-in <strong>&quot;Showcase&quot;</strong> module transforms your product catalog, service list, and warehouse inventory into an autonomous, lightning-fast, and modern online storefront. You get an independent public platform free from recurring platform fees and vulnerable server-side content management systems.</p><p>The storefront is compiled using modern Jamstack static site generation (SSG). The output is a clean bundle of autonomous files: HTML5 markup, CSS3 styling, vanilla JavaScript logic, and modern WebP and AVIF raster graphics.</p><p>The resulting website opens instantly on mobile devices and desktop computers, requires no server database, and can be hosted for free or minimal cost on high-availability infrastructures: S3 object storage buckets, direct Cloudflare Pages deployment, GitHub Pages, or traditional hosting environments via FTP.</p><hr><h2 id="architecture-of-independence-advantages-of-a-sovereign-showcase" tabindex="-1">Architecture of Independence: Advantages of a Sovereign Showcase <a class="header-anchor" href="#architecture-of-independence-advantages-of-a-sovereign-showcase" aria-label="Permalink to &quot;Architecture of Independence: Advantages of a Sovereign Showcase&quot;">​</a></h2><p>The storefront is engineered specifically for craftspeople, makers, service engineers, and local studios. The architecture removes intermediaries between creator and buyer.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Storefront Subsystem</th><th style="text-align:left;">Function in OmniCraft ERP</th><th style="text-align:left;">Practical Benefit for Your Business</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>&quot;Delicate Premium&quot; Aesthetic</strong></td><td style="text-align:left;">Standalone Inter WOFF2 typography, brass accents, light and dark themes</td><td style="text-align:left;">High-end visual presentation of manual craftsmanship without relying on external font servers</td></tr><tr><td style="text-align:left;"><strong>Multi-Page Architecture</strong></td><td style="text-align:left;">Homepage with hero section, filtered catalog, detailed cards, shipping guides, and journal</td><td style="text-align:left;">A complete brand website instead of a rudimentary single-page price list</td></tr><tr><td style="text-align:left;"><strong>Modular Item Cards</strong></td><td style="text-align:left;">Block constructor: lead intro, feature grid, craft story, photo gallery, video, spec table, FAQs</td><td style="text-align:left;">Compelling presentation of bespoke pieces, series runs, and technical services</td></tr><tr><td style="text-align:left;"><strong>Sovereign Checkout &amp; E2EE</strong></td><td style="text-align:left;">Serverless cart, client-side encryption via RSA-2048 and AES-256-GCM, Telegram Bot, and forms</td><td style="text-align:left;">Complete sovereignty: customer personal data is readable only by the owner</td></tr><tr><td style="text-align:left;"><strong>Built-in Live Preview</strong></td><td style="text-align:left;">Embedded multi-threaded web server with strict no-cache headers</td><td style="text-align:left;">Instant verification in your local browser before publishing live</td></tr><tr><td style="text-align:left;"><strong>Flexible Site Deployment</strong></td><td style="text-align:left;">Direct Cloudflare upload, S3 bucket sync, FTP/SFTP upload, local ZIP export</td><td style="text-align:left;">Near-zero hosting costs and ultra-fast incremental deployments via SHA-256 checksums</td></tr><tr><td style="text-align:left;"><strong>Unified Order Inbox</strong></td><td style="text-align:left;">Centralized order intake, smart clipboard parsing, quick replies, FIFO inventory deduction</td><td style="text-align:left;">Eliminates manual transcription mistakes while ensuring physical stock integrity</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Freedom from Third-Party Subscriptions and Commissions</p><p>Unlike cloud website builders, an <strong>OmniCraft ERP</strong> storefront cannot be disabled by platform bans, does not extract transaction commissions, and never injects third-party advertisements. Your customer database, source assets, and deployed site remain 100% under your ownership.</p></div><hr><h2 id="showcase-structure-and-capabilities" tabindex="-1">Showcase Structure and Capabilities <a class="header-anchor" href="#showcase-structure-and-capabilities" aria-label="Permalink to &quot;Showcase Structure and Capabilities&quot;">​</a></h2><h3 id="_1-universal-modular-home-page" tabindex="-1">1. Universal Modular Home Page <a class="header-anchor" href="#_1-universal-modular-home-page" aria-label="Permalink to &quot;1. Universal Modular Home Page&quot;">​</a></h3><p>The home page adapts seamlessly across diverse crafts — from bespoke leather goods and wood ateliers to electronic repair centers and hybrid studios. Every section is independently configurable:</p><ul><li><strong>Top Notification Ribbon:</strong> Optional header banner for holiday announcements, lead times, or booking slots. Visitors can dismiss the bar, and their preference persists throughout their session.</li><li><strong>Three Hero Layouts:</strong><ul><li><em>&quot;Triptych&quot;</em> — balanced three-column composition highlighting signature works;</li><li><em>&quot;Split Screen&quot;</em> — modern 50/50 balance between brand narrative and imagery;</li><li><em>&quot;Wide Banner&quot;</em> — cinematic full-width hero with balanced contrast darkening.</li></ul></li><li><strong>Manual Banner Slider:</strong> Supports 1 to 3 curated slides with manual control (navigation arrows, indicator dots, mobile touch swipes). Intrusive automatic scrolling is disabled so visitors can examine details without distraction. If custom banners are absent, the system displays your first published item automatically.</li><li><strong>Banner Inquiry Action:</strong> When Telegram or WhatsApp accounts are enabled, the wide banner presents an instant &quot;Ask a Question&quot; button that connects the client directly to your messenger.</li><li><strong>Twelve Modular Sections:</strong> Trust badge row with vector iconography, category gallery with 3:4 portrait cards, new arrivals and featured items, compact tabbed price list, full-width promo banner, production stages, the &quot;Craftsman Note&quot; section (with portrait, credentials, and facsimile signature), journal stories, customer testimonials, interactive FAQ accordions, and a concluding messenger invitation.</li><li><strong>Full-Screen Navigation Overlay:</strong> The menu toggle opens a frosted glass full-screen overlay. Structure is divided into two distinct columns: catalog departments on the left, brand story, shipping policies, and direct contact channels on the right.</li><li><strong>Adaptive Navigation Floating Button:</strong> Hidden on the initial screen to avoid visual clutter. As the user scrolls, a subtle floating button appears pointing toward footer contact channels, flipping upwards in lower sections for an immediate return to the top.</li></ul><hr><h3 id="_2-item-service-detail-page" tabindex="-1">2. Item &amp; Service Detail Page <a class="header-anchor" href="#_2-item-service-detail-page" aria-label="Permalink to &quot;2. Item &amp; Service Detail Page&quot;">​</a></h3><p>Each item page reflects deep appreciation for high craftsmanship and engineering precision:</p><ul><li><strong>Kinematic 3D Triptych Gallery:</strong> Full-width first-screen slider with simulated depth perspective. The active central frame is flanked by angled previews, offering a tactile impression of scale and materials.</li><li><strong>Floating Discovery Badge:</strong> Positioned over the lower border of the gallery, presenting the item name, price tag, an anchor link to specifications, and an interactive modifier trigger (&quot;OTHER COLORS&quot;, &quot;LEATHER OPTIONS&quot;).</li><li><strong>Two-Column Detail Layout:</strong><ul><li><em>Sticky Purchase Column:</em> Stays pinned during scrolling. Keeps prominent pricing, customizable prefixes (&quot;from &quot;), option selectors, a substantial cart button, instant messenger shortcuts, and shipping conditions in clear view.</li><li><em>Craft Narrative Column:</em> Storytelling area featuring classic drop caps, bulleted technical highlights, direct maker quotes, and modular content blocks.</li></ul></li><li><strong>Modular Storytelling Blocks:</strong><ul><li><em>Introductory Lead:</em> Concise, evocative overview set in large typography;</li><li><em>Feature Grid:</em> Icon cards detailing material selection and construction techniques;</li><li><em>Making-of Story:</em> Narrative detailing leather carving, metal tempering, or bespoke calibration;</li><li><em>Secondary Lookbook:</em> High-resolution gallery capturing the item in everyday context;</li><li><em>Lightweight Video Player:</em> Privacy-respecting facade for VK, Rutube, or YouTube videos (external scripts do not load until the user clicks play);</li><li><em>Technical Specifications:</em> Structured data table covering dimensions, raw materials, hardware grades, and net weight;</li><li><em>Product FAQs:</em> Expandable accordion answering maintenance and warranty inquiries.</li></ul></li></ul><hr><h3 id="_3-sovereign-checkout-end-to-end-data-protection" tabindex="-1">3. Sovereign Checkout &amp; End-to-End Data Protection <a class="header-anchor" href="#_3-sovereign-checkout-end-to-end-data-protection" aria-label="Permalink to &quot;3. Sovereign Checkout &amp; End-to-End Data Protection&quot;">​</a></h3><p>OmniCraft ERP implements a privacy-first checkout pipeline that keeps buyer data shielded from third-party tracking:</p><ol><li><strong>Three Customer Contact Options:</strong><ul><li><em>Direct Telegram Chat:</em> Launches your messenger with a pre-filled item order summary;</li><li><em>Direct WhatsApp Chat:</em> Instantly opens a chat containing selected options and total cost;</li><li><em>Serverless Web Cart:</em> Familiar browser shopping cart operating entirely client-side.</li></ul></li><li><strong>Client-Side End-to-End Encryption (E2EE):</strong><ul><li>Customer details (full name, phone number, shipping address, notes) are encrypted inside the customer&#39;s browser using AES-256-GCM.</li><li>The symmetric encryption key is sealed using an asymmetric RSA-OAEP 2048-bit algorithm with the storefront&#39;s public key generated during compilation.</li><li>The private decryption key is stored strictly within your local <strong>OmniCraft ERP</strong> database on your personal computer, secured by the Windows Data Protection API (DPAPI).</li><li>Neither the web host nor network intermediaries possess the capability to decrypt customer personal data.</li></ul></li><li><strong>Dual Gateway Transport:</strong><ul><li><em>Official Telegram Bot API:</em> Secure transmission of encrypted payloads directly into your studio channel;</li><li><em>Yandex Forms Gateway:</em> Domestic structured web form gateway with spam defense and spreadsheet exports.</li></ul></li><li><strong>Legal Compliance Suite:</strong><ul><li>The compiler generates standard Privacy Policy (<code>/pages/privacy</code>) and Terms of Service (<code>/pages/terms</code>) templates populated with your registered business credentials.</li><li>The web checkout includes a mandatory consent checkbox linked directly to both legal agreements.</li></ul></li></ol><hr><h2 id="step-by-step-guide-from-configuration-to-first-deployment" tabindex="-1">Step-by-Step Guide: From Configuration to First Deployment <a class="header-anchor" href="#step-by-step-guide-from-configuration-to-first-deployment" aria-label="Permalink to &quot;Step-by-Step Guide: From Configuration to First Deployment&quot;">​</a></h2><h3 id="step-1-site-administration-settings" tabindex="-1">Step 1. Site Administration Settings <a class="header-anchor" href="#step-1-site-administration-settings" aria-label="Permalink to &quot;Step 1. Site Administration Settings&quot;">​</a></h3><p>Open the <strong>&quot;Showcase&quot;</strong> tab → select the <strong>&quot;Site Administration&quot;</strong> sub-tab. The sidebar organizes settings into four focused tiers:</p><ol><li><strong>&quot;1. BRAND &amp; DESIGN&quot;:</strong><ul><li><strong>Brand &amp; Contacts:</strong> Upload vector SVG or raster logos (WebP, PNG, JPG). Choose your uploaded logo palette (light, dark, or multicolored) to guarantee crisp contrast across themes. Set default color themes (light, dark, or system auto) and select product backdrop tones (studio shadows or &quot;Transparent / No Backdrop&quot;). Provide an international phone number (+7 / global standard), business address, and links to your social channels.</li><li><strong>Home &amp; Navigation Menu:</strong> Select a quick-start profile (&quot;Craft Atelier&quot;, &quot;Services &amp; Repairs&quot;, or &quot;Products &amp; Services&quot;). Configure banner sliders and reorder home page sections. On the <strong>Navigation Menu</strong> tab, the right column combines selected pages and custom links. Click <strong>Add Item</strong> to add a link and use <strong>Move Up</strong> or <strong>Move Down</strong> to change the order.</li><li><strong>Homepage banner.</strong> Expand <strong>“First screen”</strong>, choose a layout, then set the copy and buttons. The wide banner supports up to three slides. If an <a href="./../global-settings">external agent</a> edited the banner after you opened the editor, copy your draft, reopen site settings, and apply the edits to the latest version. The section starts collapsed. The app remembers its expanded or collapsed state immediately and restores it when you restart.</li><li><strong>Promotional banner.</strong> On the <strong>“Home Page”</strong> tab, expand <strong>“Mid-Page Feature / Custom Order Banner”</strong>. Enter the offer text, add an image, and choose the button destination. Turn on the block and click <strong>“Save Changes”</strong>.</li><li><strong>Workflow steps.</strong> On the <strong>“Home Page”</strong> tab, expand <strong>“Workflow Steps (How We Work)”</strong>. Add steps in the order customers will follow them, then click <strong>“Save Changes”</strong>. If an <a href="./../global-settings">external agent</a> changed the same block, copy your edits and reopen site settings before saving.</li><li><strong>Announcement above the page.</strong> In <strong>“Announcement bar”</strong>, turn on the bar, enter the announcement text, and add a link label and destination if needed.</li><li><strong>Trust cards.</strong> In <strong>“Trust Highlights (3-4 items)”</strong>, choose an icon, title, and description for each card. Put the cards you want customers to see in the first four positions. Click <strong>“Save Changes”</strong>. If you remove every card, the strip disappears the next time you build the storefront.</li><li><strong>Directions grid.</strong> In the editor for each category you want to include, select <strong>“Show in directions grid”</strong>. On the <strong>“Home Page”</strong> tab, open <strong>“Categories &amp; Directions Grid”</strong>, turn on the block, enter the title and subtitle, and arrange the cards. Click <strong>“Save Changes”</strong>. If the selection changed while you were reordering the cards, reopen site settings and arrange them again.</li><li><strong>Best sellers.</strong> On the <strong>Home Page</strong> tab, expand the <strong>Featured / Best Sellers Block</strong>. <strong>Automatic</strong> ranks items by units sold across all channels. <strong>Sales period</strong> defaults to 90 days. Choose another preset or set dates under <strong>Custom range</strong>.</li><li><strong>Save best sellers.</strong> Click <strong>“Save Changes”</strong> to apply the block settings and manual pins together. If an <a href="./../global-settings">external agent</a> changed the same block, reopen site settings and make your edits again.</li><li><strong>New arrivals.</strong> Turn on <strong>“New Arrivals Block”</strong> on the <strong>“Home Page”</strong> tab and set the title and item count. <strong>“Automatic”</strong> shows items added to the storefront most recently. For <strong>“Manual”</strong>, select <strong>“New arrival”</strong> under <strong>“Model &amp; Specs”</strong> on the relevant product card. The selection only includes items customers can see on the storefront.</li><li><strong>Catalog on the home page.</strong> On the <strong>“Home Page”</strong> tab, expand <strong>“Home Catalog &amp; Card Format”</strong>. Choose a display mode and enter a title. In auto and compact modes, <strong>“Items Limit”</strong> sets a cap of 2 to 48 items. Full mode shows every item visible to customers. Auto mode hides the catalog when more than 12 items are visible and the home page already shows best sellers or new arrivals.</li><li><strong>Card labels.</strong> Set the default price prefix and button text in the same block. Labels set on an individual product card take precedence. Click <strong>“Save Changes”</strong> and check the result in the preview. If an external agent changed the catalog settings, reopen the editor and apply your edits again.</li><li><strong>Craftsman note.</strong> On the <strong>“Home Page”</strong> tab, expand <strong>“Craftsman Word / Manifesto”</strong>. Turn on the block, then enter a title, author caption, and quote. Click <strong>“Upload Portrait”</strong> to choose a photo. Use <strong>“Add Metric”</strong> to include a fact such as 15 years of experience. Click <strong>“Save Changes”</strong> and review the section in the preview. If an external agent edited the same block after you opened the form, reopen the editor and apply your edits again.</li><li><strong>Journal on the home page.</strong> Open <strong>“Journal &amp; Articles on Home”</strong>, turn on the block, enter a title, and set <strong>“Items Limit”</strong> to 1–9 posts. Click <strong>“Save Changes”</strong> and check the preview. The block appears when the site journal is enabled and the selected storefront has published posts. The link at the top of the block opens the full journal.</li><li><strong>Reviews and examples of work.</strong> On the <strong>“Home Page”</strong> tab, expand <strong>“Client Reviews &amp; Cases”</strong>. Turn on the block and enter a title and subtitle. Click <strong>“Add Review / Case”</strong>, fill in <strong>“Client Name”</strong> and <strong>“Review / Case Summary”</strong>, and choose a rating from 1 to 5. Add the name of the work and a photo if needed. Arrange the cards, click <strong>“Save Changes”</strong>, and check the order in the preview. The block is hidden when the list is empty.</li><li><strong>Frequently asked questions.</strong> On the <strong>“Home Page”</strong> tab, expand <strong>“FAQ Accordion”</strong>, turn on the block, and click <strong>“Add Question”</strong>. Enter a question and answer, arrange the cards, then click <strong>“Save Changes”</strong>. The block appears on the storefront when it contains at least one complete question and answer.</li><li><strong>Order terms.</strong> Expand <strong>“Order Terms &amp; Direct Contact”</strong>. Turn on the block and choose which delivery and payment details to show. You can set the button text and destination. To restore the usual contact action, select <strong>“Use the default contact button”</strong> and clear the button text.</li><li><strong>Home page template.</strong> Choose a template and click <strong>“Apply Preset”</strong>. Review the populated fields and adjust them as needed. Images, slides, and section order are kept. Click <strong>“Save Changes”</strong> to apply the template and your edits together. If someone has already changed the home page settings, reopen the editor and repeat your edits.</li><li><strong>Pin best sellers.</strong> Click <strong>Add manually</strong>, search by product name, and select an item. Pinned items appear first. Use <strong>Move up</strong> and <strong>Move down</strong> to reorder them. You can also set or clear the same mark under <strong>Featured on home</strong> in the product card.</li><li><strong>Check the list.</strong> Review the <strong>On the homepage</strong> list. The number in parentheses is the number of units sold in the selected period. Items under <strong>Outside the homepage limit</strong> are still available to pin. If there were no sales, add items manually. <strong>Manual</strong> mode shows pinned items up to the limit. The site hides the block when the list is empty.</li></ul></li><li><strong>&quot;2. CATALOG &amp; CONTENT&quot;:</strong><ul><li>Open <strong>“Catalog Settings”</strong> to configure product cards and catalog sections. <ol><li>On the <strong>“Product Types”</strong> tab, click the pencil button beside the base type and select shared fields such as color. Other types inherit the selected fields automatically. To hide a field for one type, clear its checkbox in that type&#39;s editor. It moves to <strong>“Disabled inherited attributes”</strong>. Select it again to make the saved value available on the product card. <ul><li>Set entry rules for each type. For a bag, enable the shoulder strap and strap length fields. Set the length field to appear when the strap field is <strong>“Yes”</strong>. Change the dependent rule before disabling the field that controls it.</li><li>To check assignments on the active storefront, click the type name or the <strong>“Products”</strong> button with the count. The dialog shows the attributes and the total number of cards, including unpublished and archived ones. Click a product row to open its card. <strong>“Load more”</strong> adds 10 rows at a time.</li></ul></li><li>In <strong>“Attributes”</strong>, name the fields. For single or multiple choice, enter one value per line. For a numeric attribute, enter a unit of measure. Turn on <strong>“Use as catalog filter”</strong> when customers need to filter by that field.</li><li>On the <strong>“Attribute Groups”</strong> tab, select <strong>“Add Group”</strong>. Name the group and select its fields. Then select the group in each applicable type editor. Changes to the group reach all linked types. Each field appears once, even if several sources provide it. Disabled inherited fields stay disabled when you link a group.</li><li>In <strong>“Categories”</strong>, set up sections and choose a default type for new cards. Moving an existing product to a different category keeps its type. Enter comma-separated codes in <strong>“Filter order by attribute code”</strong> to choose and order the filters. Leave the field blank to pick filters automatically from products in the section. A subcategory address includes the parent section, as in <code>/catalog/remni/neproshitye/</code>.</li><li>In <strong>“Product Variants”</strong>, select <strong>“By model or group code”</strong> to link cards of the same model. If a model has several groups, enter the same <strong>“Variant group code”</strong> for every card in each group. Use color, size, and other attributes to label the options. Select <strong>“Save Variant Settings”</strong>.</li></ol></li><li>In <strong>“Storefront Products”</strong>, leave publication switched off to save a draft and finish it later. The editor identifies required fields before publishing. Select <strong>“Missing attributes”</strong> to find already published cards that need more information. To make Unstitched a subcategory, open its editor and choose Belts in the <strong>“Parent category”</strong> field. Choose <strong>“Top level”</strong> for a standalone category. Use the editor to add a short description and upload a poster. The poster appears at the top of the category page and serves as the cover of its homepage card. The <strong>View products</strong> button scrolls to the item list.</li><li><strong>Information Pages:</strong> Populate &quot;Shipping &amp; Payment&quot;, &quot;About Atelier&quot;, and &quot;Warranty &amp; Returns&quot; sections. Generate privacy and terms pages with your legal entity details. Set <strong>Show in main menu</strong> and <strong>Show in footer menu</strong> independently for each page. The storefront build creates a Contacts page when you provide a phone number, email address, city, or at least one visible contact channel. Edit these details under <strong>“Brand &amp; Contacts”</strong> and rebuild to update both the page and footer. A Rutube link uses the platform’s gray round R icon. In the footer and menu, the icon changes color on hover and keyboard focus. Use the same checkboxes to place the Contacts link. The build also accepts <code>/contact</code> and <code>/oplata-i-dostavka</code> when those paths are free.</li><li><strong>Blog &amp; Articles:</strong> Maintain an integrated craft journal to build organic search visibility and share workshop knowledge.</li></ul></li><li><strong>&quot;3. SALES &amp; DELIVERY&quot;:</strong><ul><li>Specify delivery options (courier, postal service, pickup) alongside accepted payment workflows.</li><li>Under <strong>&quot;Checkout &amp; Inquiries&quot;</strong>, select your preferred ordering channels, configure E2EE cryptographic keys, and set up Telegram Bot or Yandex Forms endpoints.</li></ul></li><li>Click <strong>&quot;Save Changes&quot;</strong>.</li></ol><hr><h3 id="place-a-reusable-block-on-several-pages" tabindex="-1">Place a reusable block on several pages <a class="header-anchor" href="#place-a-reusable-block-on-several-pages" aria-label="Permalink to &quot;Place a reusable block on several pages&quot;">​</a></h3><ol><li>In <strong>“Foundation and Design”</strong>, open <strong>“Regions and blocks → Block types”</strong>. Open a type to see where to use it and which settings it provides.</li><li>Click <strong>“Add block”</strong> inside the type and name the block. For example, open <strong>“Catalog recommendations”</strong>, create a block called “More services,” and set the maximum <strong>“Number of entries”</strong>. For frequently asked questions and cards, fill in the content after creating the block.</li><li>Open <strong>“Regions”</strong> and click <strong>“Add block”</strong> next to <strong>“End of content”</strong> or <strong>“Before the footer”</strong>.</li><li>Select an existing block by its name and type. Choose page types or individual pages. An exclusion takes precedence when a page is included and excluded.</li><li>Order the blocks using <strong>“Move up”</strong> and <strong>“Move down”</strong>, click <strong>“Save Changes”</strong>, and check the pages in <strong>“Live Preview”</strong>.</li></ol><table tabindex="0"><thead><tr><th>Ready-to-use block</th><th>Where it appears and what it shows</th></tr></thead><tbody><tr><td><strong>“See also”</strong></td><td>Up to four other catalog entries on a product or service page. New storefronts show it in <strong>“End of content”</strong> by default.</td></tr><tr><td><strong>“Product from the article”</strong></td><td>The entry selected in <strong>“Link catalog product”</strong> in the post editor. Add a placement to show it below posts.</td></tr></tbody></table><p>To define your own type, click <strong>“Add block type”</strong> on the <strong>“Block types”</strong> tab. Choose a <strong>“Display format”</strong>, enter the type name, and add an optional description. The display format determines the settings available to blocks of this type.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Content and entry counts update across all placements of the block on the next build. To temporarily hide it in one region, turn off <strong>“Show block”</strong>. <strong>“Remove from region”</strong> removes the placement and keeps the block available for reuse.</p></div><hr><h2 id="product-attributes-and-characteristic-groups" tabindex="-1">Product Attributes and Characteristic Groups <a class="header-anchor" href="#product-attributes-and-characteristic-groups" aria-label="Permalink to &quot;Product Attributes and Characteristic Groups&quot;">​</a></h2><p>Storefront shoppers filter craft items by specific attributes: color, size, leather type, hardware finish, and compatibility. To eliminate manual re-entry of repetitive fields across multiple products, OmniCraft ERP provides a multi-level taxonomy: standalone attributes, reusable attribute groups, and faceted catalog filters.</p><h3 id="purpose-and-attribute-group-hierarchy" tabindex="-1">Purpose and Attribute Group Hierarchy <a class="header-anchor" href="#purpose-and-attribute-group-hierarchy" aria-label="Permalink to &quot;Purpose and Attribute Group Hierarchy&quot;">​</a></h3><p>In craft workshops and repair studios, distinct product types frequently share identical technical parameters. For instance, leather belts, bags, and cardholders all require fields like &quot;Leather Grade&quot;, &quot;Thread Color&quot;, and &quot;Hardware Alloy&quot;:</p><ol><li><strong>Single Source of Truth:</strong> Creating an attribute group once allows linking it across dozens of product types.</li><li><strong>Conflict-Free Inheritance:</strong> If an attribute exists in both the base product type and an attached group, the system merges them cleanly — buyers see the field on the product card exactly once.</li><li><strong>Automated Faceted Filtering:</strong> Selected attributes automatically generate sidebar filters in your storefront catalog, allowing visitors to narrow down craft items effortlessly.</li></ol><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><p>Navigate to <strong>&quot;Store Management&quot;</strong> → <strong>&quot;2. CATALOG &amp; CONTENT&quot;</strong> → <strong>&quot;Catalog Settings&quot;</strong> sub-tab.</p><h3 id="step-by-step-guide-to-attribute-groups-and-catalog-filtering" tabindex="-1">Step-by-Step Guide to Attribute Groups and Catalog Filtering <a class="header-anchor" href="#step-by-step-guide-to-attribute-groups-and-catalog-filtering" aria-label="Permalink to &quot;Step-by-Step Guide to Attribute Groups and Catalog Filtering&quot;">​</a></h3><ol><li><strong>Define Standalone Attributes:</strong><ul><li>Open the <strong>&quot;2. Attributes&quot;</strong> sub-tab;</li><li>Click <strong>&quot;Add Attribute&quot;</strong>;</li><li>Specify system key, public storefront label, and field type (text string, numeric with units, or selectable option list);</li><li>Check <strong>&quot;In Catalog Filters&quot;</strong> for parameters you want shoppers to filter by;</li><li>Click <strong>&quot;Save&quot;</strong>.</li></ul></li><li><strong>Create an Attribute Group:</strong><ul><li>Switch to the <strong>&quot;3. Attribute Groups&quot;</strong> sub-tab;</li><li>Click <strong>&quot;Add Group&quot;</strong>;</li><li>In the modal dialog, enter a descriptive title in <strong>&quot;Group name&quot;</strong> (e.g., <em>&quot;Leather &amp; Hardware Specs&quot;</em>, <em>&quot;Physical Dimensions&quot;</em>);</li><li>Select the checkboxes for the relevant attributes from the catalog list;</li><li>Click <strong>&quot;Save&quot;</strong>. The group appears in the registry displaying its assigned fields.</li></ul></li><li><strong>Attach Groups to Product Types:</strong><ul><li>Open the <strong>&quot;1. Product Types&quot;</strong> sub-tab;</li><li>Click the pencil edit icon next to your desired product type (e.g., <em>&quot;Handmade Belts&quot;</em>);</li><li>Under the groups section, attach your created attribute group and click <strong>&quot;Save&quot;</strong>;</li><li>All group attributes become immediately available for data entry across all product cards assigned to that type.</li></ul></li><li><strong>Order Storefront Catalog Filters:</strong><ul><li>Switch to the <strong>&quot;4. Categories&quot;</strong> sub-tab;</li><li>In the target category editor, locate <strong>&quot;Filter order by codes&quot;</strong>;</li><li>Enter comma-separated attribute keys in your preferred display order (e.g., <code>color, leather_type, buckle_width</code>);</li><li>Leaving the field empty instructs the static generator to automatically sort filters based on active category stock.</li></ul></li><li><strong>Edit and Delete Attribute Groups:</strong><ul><li>To update attributes, click <strong>&quot;Edit Group&quot;</strong> on the group row. Adjustments sync automatically across all attached product types;</li><li>To remove a group, click <strong>&quot;Delete&quot;</strong>. If the group is attached to live products with populated attributes, safety validations prevent accidental data loss and report active dependencies.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">Global Core Attributes</p><p>If an attribute must appear on every product in your store without exception (e.g., &quot;Maker SKU&quot; or &quot;Country of Origin&quot;), flag it as global in the base product type. It propagates across all categories without requiring individual group attachments.</p></div><hr><h3 id="step-2-preparing-catalog-items-for-publication" tabindex="-1">Step 2. Preparing Catalog Items for Publication <a class="header-anchor" href="#step-2-preparing-catalog-items-for-publication" aria-label="Permalink to &quot;Step 2. Preparing Catalog Items for Publication&quot;">​</a></h3><ol><li>Open <strong>“Storefront Products”</strong>. A progress bar at the top of the section stays visible while the product list loads.</li><li>Toggle between the visual 3:4 portrait card grid and the compact tabular ledger.</li><li>Click any card to enter the multi-tab item editor: <ul><li><strong>1. General &amp; Pricing:</strong> Toggle <strong>&quot;Publish on website&quot;</strong>, set retail pricing, optional &quot;from &quot; prefix, badge, URL slug, category, and model.</li><li><strong>2. Media (photos):</strong> Add product photography, reorder angles, and assign the cover shot (&quot;★ Cover&quot;).</li><li><strong>3. Specifications &amp; Delivery:</strong> Fill in catalog filter attributes, set shipping packaging, parcel dimensions, and gross weight.</li><li><strong>4. Order Options:</strong> Configure selectable buyer variations (dimensions, personalized engraving, gift box packaging).</li><li><strong>5. Landing &amp; Sections:</strong> Draft rich Markdown narrative and attach promotional showcase blocks (features, craft story, video demo, FAQ).</li></ul></li><li>Click <strong>&quot;Save&quot;</strong>.</li></ol><hr><h4 id="link-cards-that-share-a-product-model" tabindex="-1">Link cards that share a product model <a class="header-anchor" href="#link-cards-that-share-a-product-model" aria-label="Permalink to &quot;Link cards that share a product model&quot;">​</a></h4><ol><li>Select the same <strong>“Product model”</strong> in each product recipe. For a stock item without a recipe, use this field in <strong>“Receive Finished Goods”</strong>. The pencil button opens the model manager where you can create, rename, or delete models.</li><li>In the storefront card, keep <strong>“From inventory”</strong> to inherit the model or choose another model for that storefront.</li><li>In <strong>“Linked Items”</strong>, enable variants and select <strong>“By model or group code”</strong>. Published cards with the same product type and model show a button for switching between variants.</li></ol><div class="info custom-block"><p class="custom-block-title">Where to find product models</p><p>Open <strong>“Site Management”</strong> → <strong>“Categories &amp; Items”</strong> → <strong>“Product models”</strong>. The list shows how many recipes and stock items are linked to each model.</p></div><h3 id="step-3-local-live-preview" tabindex="-1">Step 3. Local Live Preview <a class="header-anchor" href="#step-3-local-live-preview" aria-label="Permalink to &quot;Step 3. Local Live Preview&quot;">​</a></h3><p>Before publishing to the internet, audit your storefront in a local browser:</p><ol><li>In the top action bar, click <strong>&quot;Live Preview&quot;</strong> (eye icon).</li><li>OmniCraft ERP compiles your active database into static assets, starts a lightweight local web server, and opens your browser.</li><li>Test checkout flows, verify responsiveness across window sizes, and switch themes.</li><li>Open a category and select several of its subcategories. Check for a breadcrumb such as <code>Store / Products / Belts: Unstitched, Stitched</code>. The Belts link clears the subcategory selection. The Products link opens the full catalog and clears the filters.</li></ol><div class="info custom-block"><p class="custom-block-title">Protection Against Stale Browser Cache</p><p>The built-in preview server sends strict <code>no-cache</code> headers. Any subsequent updates saved inside OmniCraft ERP become visible immediately upon refreshing the page (F5).</p></div><hr><h3 id="step-4-site-deployment-transport-selection" tabindex="-1">Step 4. Site Deployment &amp; Transport Selection <a class="header-anchor" href="#step-4-site-deployment-transport-selection" aria-label="Permalink to &quot;Step 4. Site Deployment &amp; Transport Selection&quot;">​</a></h3><p>Under &quot;Site Administration&quot;, open <strong>&quot;Site Deployment&quot;</strong> and choose your deployment method:</p><ul><li><strong>Direct Cloudflare Pages Upload:</strong> The fastest modern transport. Bypasses Git commits by uploading only modified static files through SHA-256 checksum comparison. Includes automated SSL certification and global CDN performance.</li><li><strong>S3 Object Storage:</strong> Scalable, reliable static hosting with support for custom domains and automated synchronization.</li><li><strong>FTP / SFTP Protocol:</strong> Direct secure file transfer to your virtual private server or shared hosting account.</li><li><strong>Local Folder or ZIP Archive:</strong> Exports a complete static distribution to your drive for offline distribution or manual backup.</li><li><strong>GitHub Pages:</strong> Publishes directly to the <code>gh-pages</code> branch without manual terminal commands.</li></ul><p>Click <strong>&quot;Test Connection&quot;</strong>, then <strong>&quot;Save Transport&quot;</strong>, and click <strong>&quot;Publish Website&quot;</strong> in the header. After publishing, click <strong>&quot;Open Website&quot;</strong>. For S3, the browser opens the public address you entered. For GitHub Pages, it opens your custom domain if you set one, or the address built from the repository owner and name.</p><hr><h2 id="unified-order-inbox-processing-customer-deals" tabindex="-1">Unified Order Inbox: Processing Customer Deals <a class="header-anchor" href="#unified-order-inbox-processing-customer-deals" aria-label="Permalink to &quot;Unified Order Inbox: Processing Customer Deals&quot;">​</a></h2><p>All inbound inquiries across your storefront and external channels converge in the <strong>&quot;Order Inbox&quot;</strong> sub-tab:</p><ol><li><strong>Telegram Bot Synchronization:</strong> Clicking <strong>&quot;🔄 Sync&quot;</strong> queries the Telegram Bot API, downloads new payloads, decrypts them with your local RSA key, standardizes phone numbers to E.164, eliminates duplicates, and automatically registers clients into your CRM database.</li><li><strong>Yandex Forms Intake:</strong> Imports structured customer requests submitted through web forms with automated line-item distribution.</li><li><strong>Smart Clipboard Parsing:</strong> When conversing on Avito, social networks, or messengers, simply copy the client&#39;s message to your clipboard and click <strong>&quot;Smart Paste&quot;</strong>. The system extracts the customer name, phone number, delivery address, and requested items.</li><li><strong>Quick Reply Templates:</strong> The <strong>&quot;Reply&quot;</strong> button opens pre-formatted responses (&quot;Order Confirmed&quot;, &quot;Package Dispatched&quot;, &quot;Payment Details&quot;) and launches the client&#39;s chat.</li><li><strong>One-Click Stock Deduction:</strong> Once an order is packed, click <strong>&quot;Execute Sale&quot;</strong>. The application deducts finished inventory batches using the first-in, first-out method (FIFO) and records cash inflow in Cash Flow (DDS).</li><li><strong>Two-Phase Inventory Reservation:</strong> Incoming orders reserve available inventory immediately, preventing accidental double-selling. If stock is depleted, the order is flagged as &quot;Made to Order&quot;. Canceled deals instantly restore reserved items to available inventory.</li></ol><hr><h2 id="multi-showcases-managing-distinct-brands-on-a-single-warehouse" tabindex="-1">Multi-Showcases: Managing Distinct Brands on a Single Warehouse <a class="header-anchor" href="#multi-showcases-managing-distinct-brands-on-a-single-warehouse" aria-label="Permalink to &quot;Multi-Showcases: Managing Distinct Brands on a Single Warehouse&quot;">​</a></h2><p>If you operate multiple specialized business lines (e.g., a bespoke leather brand and an equipment restoration studio), OmniCraft ERP allows running <strong>multiple independent storefronts</strong> on a shared database:</p><ul><li>The header dropdown allows instant switching between active storefronts;</li><li>In &quot;4. DEPLOY &amp; SYSTEM&quot; → <strong>&quot;Multi-Showcases&quot;</strong>, customize individual domains, branding, and deployment credentials;</li><li>Items and services are assigned to specific storefronts while sharing common raw materials, inventory valuation, and cash flow accounting.</li></ul>',67))])}const k=r(c,[["render",u]]);export{v as __pageData,k as default};
